-- Create "system_alerts" table
CREATE TABLE "system_alerts" ("id" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL DEFAULT now(), "severity" text NOT NULL DEFAULT 'warning', "code" text NOT NULL, "source" text NOT NULL DEFAULT 'judge', "commit_id" integer NULL, "message" text NOT NULL, "details" jsonb NULL, "acknowledged_at" timestamptz NULL, "acknowledged_by" integer NULL, PRIMARY KEY ("id"), CONSTRAINT "system_alerts_acknowledged_by_fkey" FOREIGN KEY ("acknowledged_by") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "system_alerts_commit_id_fkey" FOREIGN KEY ("commit_id") REFERENCES "commits" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "system_alerts_severity_check" CHECK (severity = ANY (ARRAY['warning'::text, 'critical'::text])), CONSTRAINT "system_alerts_source_check" CHECK (source = ANY (ARRAY['judge'::text, 'backend'::text])));
-- Create index "idx_system_alerts_created_at" to table: "system_alerts"
CREATE INDEX "idx_system_alerts_created_at" ON "system_alerts" ("created_at" DESC);
-- Create index "idx_system_alerts_open" to table: "system_alerts"
CREATE INDEX "idx_system_alerts_open" ON "system_alerts" ("created_at" DESC) WHERE (acknowledged_at IS NULL);
-- Create index "system_alerts_commit_code_key" to table: "system_alerts"
CREATE UNIQUE INDEX "system_alerts_commit_code_key" ON "system_alerts" ("commit_id", "code") WHERE (commit_id IS NOT NULL);

-- Row-level security at the service-role boundary: the judge role has no grant
-- on this table, and the policy keeps it denied even if a future migration
-- grants too broadly. Added by hand because the Atlas community diff does not
-- model policies.
ALTER TABLE "system_alerts" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "runcodes_app_only" ON "system_alerts" TO PUBLIC
  USING (current_user = 'runcodes_app')
  WITH CHECK (current_user = 'runcodes_app');
